#!/usr/bin/env node
// Renders content/corrections.json to docs/content-corrections.md (reviewable ledger).
import { readFileSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const L = JSON.parse(readFileSync(join(ROOT, 'content/corrections.json'), 'utf8'));
const esc = (s) => (s || '*(addition)*').replace(/\|/g, '\\|');
const out = [
    '# Content correction ledger',
    '',
    'Generated by `node tools/render_ledger.mjs` from `content/corrections.json`. Do not edit by hand.',
    '',
    'Every reviewed string that differs from the supplied mission scripts (`rover_rush_*_script.md`) is listed here. The originals stay in those scripts and in git history; the game ships only the replacements.',
    '',
    '| Content ID | Original | Replacement | Reason | Source |',
    '| --- | --- | --- | --- | --- |',
    ...L.entries.map((e) => `| \`${e.id}\` | ${esc(e.original)} | ${esc(e.replacement)} | ${esc(e.reason)} | [${e.source}](${L.sources[e.source]}) |`),
    '',
];
writeFileSync(join(ROOT, 'docs/content-corrections.md'), out.join('\n'));
console.log(`wrote docs/content-corrections.md (${L.entries.length} entries)`);
